        core_question="If a subset A ⊂ ℕ of nonnegative integers is an asymptotic additive basis of order 2 (so every sufficiently large integer is a sum of two elements of A), must the representation count r_{A+A}(n) = |{(a, b) ∈ A² : a + b = n}| be unbounded?",
