        progress_2026="Best unconditional lower bound is merely lim sup r_{A+A}(n) ≥ 8 (Borwein-Choi-Chu 2006); shockingly, if negative integers are allowed (A ⊂ ℤ), Ruzsa constructed a basis with bounded r(n), proving the non-negativity of ℕ is essential yet still yielding no path to ∞ after 85 years!",
